import * as fs from 'node:fs';
import * as path from 'node:path';

/**
 * Normalizes any hoisted workspace symlinks generated by Bun Canary
 * that incorrectly point outside the root directory or are missing from @types.
 */
const rootDir = process.cwd();
const rootNm = path.join(rootDir, 'node_modules');

if (fs.existsSync(rootNm)) {
  fixSymlinks(rootNm);
  fixTypeDeclarations(rootNm);
}

function fixSymlinks(dir: string): void {
  let entries: fs.Dirent[];
  try {
    entries = fs.readdirSync(dir, { withFileTypes: true });
  } catch {
    return;
  }

  for (const entry of entries) {
    const fullPath = path.join(dir, entry.name);
    if (entry.isSymbolicLink()) {
      try {
        const rawTarget = fs.readlinkSync(fullPath);
        if (rawTarget.includes('.bun/') && !fs.existsSync(fullPath)) {
          const relFromNm = '.bun/' + rawTarget.split('.bun/')[1];
          const fullTarget = path.join(rootNm, relFromNm);
          if (fs.existsSync(fullTarget)) {
            const properRel = path.relative(path.dirname(fullPath), fullTarget);
            fs.unlinkSync(fullPath);
            fs.symlinkSync(properRel, fullPath);
          }
        }
      } catch (error) {
        // A broken symlink is usually harmless, but silence here made "bun install"
        // look healthy while silently skipping the workaround. surface it.
        console.warn(`[postinstall] could not repair symlink ${fullPath}:`, error);
      }
    } else if (entry.isDirectory() && entry.name.startsWith('@')) {
      fixSymlinks(fullPath);
    }
  }
}

function fixTypeDeclarations(nmDir: string): void {
  const bunDir = path.join(nmDir, '.bun');
  const typesDir = path.join(nmDir, '@types');
  if (!fs.existsSync(bunDir)) return;
  fs.mkdirSync(typesDir, { recursive: true });

  const bunEntries = fs.readdirSync(bunDir);
  for (const entry of bunEntries) {
    if (entry.startsWith('@types+')) {
      const match = /^@types\+([^@]+)@/.exec(entry);
      if (!match || !match[1]) continue;
      const typePkgName = match[1];
      const targetSymlink = path.join(typesDir, typePkgName);
      if (!fs.existsSync(targetSymlink)) {
        const candidate = path.join(bunDir, entry, 'node_modules', '@types', typePkgName);
        if (fs.existsSync(candidate)) {
          const rel = path.relative(typesDir, candidate);
          try {
            fs.symlinkSync(rel, targetSymlink);
          } catch (error) {
            console.warn(`[postinstall] could not link @types/${typePkgName}:`, error);
          }
        }
      }
    }
  }
}
